{
  "schemaVersion": "0.2",
  "slug": "grid",
  "name": "Grid",
  "status": "experimental",
  "purpose": "Two-dimensional layout container for aligning child elements.",
  "scenarios": [
    "Align cards in a dashboard",
    "Create a form layout",
    "Build a responsive gallery"
  ],
  "props": {
    "children": {
      "type": "node",
      "required": true,
      "description": "Grid items."
    },
    "columns": {
      "type": "number",
      "required": false,
      "description": "Default column count.",
      "default": 1
    },
    "gap": {
      "type": "enum",
      "required": false,
      "description": "Gap between items.",
      "values": [
        "none",
        "sm",
        "md",
        "lg"
      ],
      "default": "md"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "gap",
      "values": [
        "none",
        "sm",
        "md",
        "lg"
      ],
      "default": "md",
      "description": "Gap between items."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Grid laid out."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page",
      "card"
    ],
    "allowedChildren": [
      "card",
      "stack",
      "form"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use Grid for one-dimensional layouts; use Stack.",
    "Do not nest deeply."
  ],
  "a11y": {
    "role": "generic",
    "keyboard": [],
    "focus": "Children remain focusable in document order.",
    "labeling": "Not a landmark.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Column count can be overridden by media queries externally.",
    "breakpoints": {
      "compact": "Columns may collapse via external CSS.",
      "medium": "Configured columns.",
      "large": "Configured columns."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "CSS Grid with logical gaps.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "grid",
    "states": [
      "default"
    ],
    "intents": [
      "layout-columns"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export interface GridProps {
  children: ReactNode
  columns?: number
  gap?: 'none' | 'sm' | 'md' | 'lg'
  className?: string
}

export function Grid({ children, columns = 1, gap = 'md', className }: GridProps) {
  const classes = ['cu-grid', 'cu-grid--gap-' + gap, className].filter(Boolean).join(' ')
  return (
    <div
      className={classes}
      data-ai-role="grid" data-ai-state="default" data-ai-intent="layout-columns"
      style={{ gridTemplateColumns: 'repeat(' + columns + ', minmax(0, 1fr))' }}
    >
      {children}
    </div>
  )
}

.cu-grid {
  display: grid;
}

.cu-grid--gap-none {
  gap: 0;
}

.cu-grid--gap-sm {
  gap: var(--cu-space-1);
}

.cu-grid--gap-md {
  gap: var(--cu-space-2);
}

.cu-grid--gap-lg {
  gap: var(--cu-space-3);
}
